"""Restore client sessions from a resume blob."""

import ast
import base64
import binascii
import hashlib
import hmac
import json
import os
import re
import time
from pathlib import Path

CACHE_DIR = Path("/tmp/sessioncache")
SESSION_TTL = 3600  # seconds a session stays valid after issued_at

_SESSION_ID_RE = re.compile(r"[A-Za-z0-9_-]{1,128}")


class InvalidSession(ValueError):
    """The resume blob is malformed, forged, or expired."""


def _secret() -> bytes:
    key = os.environ.get("SESSIONSVC_SECRET")
    if not key:
        raise RuntimeError("SESSIONSVC_SECRET must be set")
    return key.encode()


def _sign(payload: bytes) -> bytes:
    return hmac.new(_secret(), payload, hashlib.sha256).digest()


def make_blob(session: dict) -> str:
    """Build a signed resume blob for a session, stamping issued_at."""
    payload = json.dumps({**session, "issued_at": time.time()}).encode()
    return base64.b64encode(payload + _sign(payload)).decode()


def _is_expired(issued_at: object, now: float) -> bool:
    if isinstance(issued_at, bool) or not isinstance(issued_at, (int, float)):
        return True
    return now - issued_at > SESSION_TTL or issued_at > now + 60


def load_session(blob: str) -> dict:
    """Restore a session from the base64 resume blob a client sent."""
    purge_expired()
    try:
        data = base64.b64decode(blob, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise InvalidSession("malformed blob") from exc
    payload, sig = data[: -hashlib.sha256().digest_size], data[-hashlib.sha256().digest_size :]
    if not hmac.compare_digest(sig, _sign(payload)):
        raise InvalidSession("bad signature")
    try:
        session = json.loads(payload)
    except ValueError as exc:
        raise InvalidSession("malformed blob") from exc
    if not isinstance(session, dict) or _is_expired(session.get("issued_at"), time.time()):
        raise InvalidSession("session expired")
    return session


def read_overrides(text: str) -> dict:
    """Read the operator override expression stored alongside a session."""
    return ast.literal_eval(text)


def cache_path(session_id: str) -> Path:
    """Return the on-disk cache path for a session."""
    if not _SESSION_ID_RE.fullmatch(session_id):
        raise ValueError("invalid session id")
    return CACHE_DIR / (session_id + ".session")


def save_session(session_id: str, session: dict) -> None:
    """Persist a session to the on-disk cache, recording when it was issued."""
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    record = {**session, "issued_at": time.time()}
    cache_path(session_id).write_text(json.dumps(record))


def purge_expired() -> int:
    """Delete expired or unreadable entries from the on-disk cache; return the count."""
    if not CACHE_DIR.is_dir():
        return 0
    now = time.time()
    removed = 0
    for path in CACHE_DIR.glob("*.session"):
        try:
            issued_at = json.loads(path.read_text()).get("issued_at")
        except (OSError, ValueError, AttributeError):
            issued_at = None
        if _is_expired(issued_at, now):
            try:
                path.unlink()
                removed += 1
            except OSError:
                pass
    return removed
